from lib import *
S = SS('g22')
steps = [
    step("栈展开与 recover:level1 → level2 → level3,level3 先打印“即将 panic”然后 panic;展开时按调用栈从内到外执行 defer:level3 的 defer、level2 的 defer、level1 的 defer;level1 的 defer 里 recover 到 \"boom\",把它转成 error 返回,函数正常返回:level1 的 err = recover 到:boom。level2 里 panic 之后的语句没有执行。", t=tl(S(1)), done=lidx(S(1), 'level3:即将 panic', 'level3 的 defer', 'level2 的 defer'), mark=lidx(S(1), 'level1 的 defer', 'level1 返回的 err'), kv=KV([['展开顺序', 'level3 的 defer → level2 的 defer → level1 的 defer'], ['recover 的位置', '只有 level1 的 defer 里'], ['结果', 'level1 正常返回,err = recover 到:boom']], ['recover 的位置'])),
    step("recover 必须由被 defer 的函数直接调用:defer 里调用 helper(),helper 里的 recover() 返回 nil(没有接住),panic 继续,被外层 defer 接住:外层 defer 才接住:p1;直接写 defer recover() 也不起作用,panic 被另一个 defer 接住:外层 defer 接住了:p2。", t=tl(S(2)), done=lidx(S(2), 'helper()'), mark=lidx(S(2), 'nestedRecover()', 'deferRecoverDirect()'), kv=KV([['defer 的函数里直接调用 recover()', '有效'], ['defer 的函数调用的 helper 里的 recover()', '返回 nil,没接住'], ['defer recover()', '不起作用']], ['defer 的函数里直接调用 recover()'])),
    step("runtime.Goexit:在 goroutine 里调用 Goexit,defer 会执行,defer 里的 recover() 返回 nil(没有 panic 可接),Goexit 之后的语句不执行,WaitGroup 正常完成。", t=tl(S(3)), mark=lidx(S(3), 'Goexit 期间'), kv=KV([['runtime.Goexit()', '退出当前 goroutine,不是 panic'], ['defer', '正常执行'], ['recover()', '返回 nil']], ['runtime.Goexit()'])),
    step("panic(nil) 与 runtime.Error:panic(nil) 之后 recover() = runtime error: panic called with nil argument,类型是 *runtime.PanicNilError;除以 0:recover() = runtime error: integer divide by zero,类型 runtime.errorString,实现 runtime.Error;越界:runtime error: index out of range [5] with length 1。", t=tl(S(4)), done=lidx(S(4), 'panic(nil)'), mark=lidx(S(4), '除以 0', '越界'), kv=KV([['panic(nil)', 'recover() 得到 *runtime.PanicNilError'], ['除以 0', 'runtime.errorString,实现 runtime.Error'], ['越界', 'index out of range [5] with length 1']], ['panic(nil)'])),
    step("没被 recover 的 panic(每个情形是独立进程,退出码都是 2):defer 里再 panic 且没有 recover:打印 panic: 第一个 panic 与缩进的 panic: 第二个 panic(在 defer 里);第一个 panic 被 recover 后 defer 里又 panic:只打印 panic: 第二个 panic;recover 之后重新 panic:panic: 原始 panic [recovered] 与缩进的 panic: 重新 panic:原始 panic;main 里 recover 不了另一个 goroutine 的 panic:退出码 2;main 里调用 runtime.Goexit:main 的 defer 执行了、另一个 goroutine 正常结束,最后 fatal error: no goroutines (main called runtime.Goexit) - deadlock!(退出码 2)。", t=tl(S(5)), done=lidx(S(5), '退出码 2'), mark=lidx(S(5), '[recovered]', '(缩进)panic:', 'fatal error: no goroutines'), kv=KV([['panic 链', '后面的 panic 缩进显示;被 recover 的标 [recovered]'], ['另一个 goroutine 的 panic', 'main 里的 recover 接不住,退出码 2'], ['main 里 Goexit', '等其它 goroutine 结束后 fatal error: no goroutines']], ['panic 链'])),
    step("panic(nil) 的旧语义:默认(Go 1.27.1)recover() = runtime error: panic called with nil argument;GODEBUG=panicnil=1 时 recover() = nil。godebug 文档写的是:Go 1.21 引入 panicnil 设置,默认 panicnil=0 让 panic(nil) 成为运行时错误,panicnil=1 恢复 Go 1.20 及更早的行为。", t=tl(S(6)), done=lidx(S(6), '默认'), mark=lidx(S(6), 'GODEBUG=panicnil=1'), kv=KV([['默认', 'recover() = runtime error: panic called with nil argument'], ['GODEBUG=panicnil=1', 'recover() = nil(旧行为)']], ['GODEBUG=panicnil=1'])),
]
A = mkartg('g22', 22, 'Go,panic,recover,Goexit,defer,真实验证,动画演示',
    '在 Go 1.27.1 里验证 panic 展开时 defer 从内到外执行、recover 只在被 defer 的函数里直接调用才有效(helper 里的 recover 与 defer recover() 都不行);runtime.Goexit 会执行 defer 但 recover 返回 nil;panic(nil) 变成 *runtime.PanicNilError,GODEBUG=panicnil=1 恢复旧行为;panic 链的打印格式;recover 接不住别的 goroutine 的 panic;main 里 Goexit 的 fatal error。',
    'panic、recover 与 Goexit 都会触发 defer,但行为各有不同。这篇用真实程序逐个验证:展开时 defer 的顺序、recover 到底在哪里有效、Goexit 与 panic 的差别、panic(nil) 的变化,以及未被 recover 的 panic 打印什么。',
    [('从内到外', 'panic 展开时 defer 的执行顺序:level3 → level2 → level1'), ('直接调用', 'recover() 必须由被 defer 的函数直接调用,helper 里调用或 defer recover() 都不接住'), ('GODEBUG=panicnil=1', 'panic(nil) 的 recover 结果:默认是 PanicNilError,设置后是 nil')],
    [('展开顺序', '<p>panic 发生后,运行时沿着调用栈从最内层往外执行每个函数的 defer,直到有一个 defer 里的 <code>recover()</code> 接住它;那个函数随后正常返回给自己的调用者。中间那些函数里 panic 点之后的语句不会执行。</p>'),
     ('recover 的位置', '<p>语言规范要求 <code>recover</code> 必须由<b>被 defer 的函数</b>直接调用才有效。实验里在 defer 的函数里调用 <code>helper()</code>、<code>helper</code> 里再 <code>recover()</code>,得到 <code>nil</code>;写成 <code>defer recover()</code> 也不起作用。常见的错误就是把 recover 包进一个通用的 helper。</p>'),
     ('Goexit', '<p><code>runtime.Goexit</code> 终止当前 goroutine,但会先执行所有 defer。它不是 panic,所以 defer 里的 <code>recover()</code> 返回 <code>nil</code>。在 <code>main</code> 里调用它,等其它 goroutine 都结束后程序以 <code>fatal error: no goroutines (main called runtime.Goexit) - deadlock!</code> 终止。</p>'),
     ('panic(nil) 与运行时错误', '<p>Go 1.21 起 <code>panic(nil)</code> 会变成 <code>*runtime.PanicNilError</code>,使 <code>recover()</code> 的 <code>nil</code> 只表示“没有 panic”。除以零、下标越界等运行时错误实现了 <code>runtime.Error</code> 接口,可以用类型断言区分。</p>'),
     ('没接住的 panic', '<p>panic 在 defer 里再 panic、或 recover 后重新 panic,打印时会形成链(后面的缩进、被接住的标 <code>[recovered]</code>);<b>recover 只对本 goroutine 有效</b>,另一个 goroutine 的 panic 会让整个进程以退出码 2 结束。所以起 goroutine 时要在 goroutine 内部自己 recover。</p>'),
     ('旧行为的开关', '<p>godebug 文档说明 <code>panicnil</code> 是 Go 1.21 引入的设置,go.mod 里写 <code>go 1.20</code> 时默认就是 <code>panicnil=1</code>。上面实验直接用环境变量切换,验证了两种结果。</p>')],
    steps,
    [ENV_G + '。每个“没被 recover”的情形都是同一个程序用不同命令行参数起的独立进程,退出码与输出来自真实进程;读过的资料:doc/godebug.md 里关于 panicnil 的说明',
     '没有验证:panic 与 recover 的运行时实现(栈展开的数据结构)、defer 链里多个 recover 的交互(只试了一个)、cgo 回调中的 panic、signal 触发的 panic(如 nil 指针解引用)的细节、Goexit 在 init 函数里的行为'],
    'panic、recover 与 Goexit')
